#!/usr/bin/env python
"""Revert a resharded dataset (created by compress.py) to its original
structure and contents, in place.

For every original file recorded in ``.reshard-index.json`` at the root
of the resharded tree, the recorded chunk files are concatenated (in
order) back into the original file, creating the original directory
hierarchy, and the file's mode and modification time are restored.
Empty original directories are recreated.  After every file has been
verified byte-for-byte (via size, and against the index when sizes are
available), the chunk tree and the index are removed, leaving exactly
the original tree in place.

The operation is safe to re-run to completion: it is idempotent as long
as it is not interrupted, and a run interrupted mid-way can be finished
by running it again (the original files written so far are rewritten
from the chunks, which are still intact).

Usage:
    python decompress.py <resharded_dir>
"""

from __future__ import annotations

import json
import os
import sys

MAX_ENTRIES_PER_DIR = 30
MAX_FILE_SIZE = 15 * 1000 * 1000  # 15 MB (15,000,000 bytes)
CHUNK_ROOT = ".__reshard__"
INDEX_NAME = ".reshard-index.json"
BUFFER = 1024 * 1024  # 1 MiB copy buffer


def fail(message):
    sys.exit("decompress: %s" % message)


def load_index(resharded_dir):
    index_path = os.path.join(resharded_dir, INDEX_NAME)
    if not os.path.isfile(index_path):
        fail(
            "no %s found in %s; is this a resharded directory produced by "
            "compress.py?" % (INDEX_NAME, resharded_dir)
        )
    with open(index_path, "r") as f:
        index = json.load(f)
    return index_path, index


def verify_index(index):
    for entry in index.get("files", []):
        size = entry["size"]
        expected = 0
        for chunks in entry.get("chunks", []):
            expected += chunks[1]
        if size and expected != size:
            fail("index is corrupt: size mismatch for %s" % entry["path"])
    if index.get("max_entries_per_dir") != MAX_ENTRIES_PER_DIR:
        fail("index was not written with the 30-entry directory limit")
    if index.get("max_file_size") != MAX_FILE_SIZE:
        fail("index was not written with the 15 MB file limit")


def verify_chunks(resharded_dir, index):
    """Check that every recorded chunk exists with exactly the recorded size."""
    seen = set()
    for entry in index.get("files", []):
        for rel, size in entry.get("chunks", []):
            if rel in seen:
                fail("index lists chunk %s more than once" % rel)
            seen.add(rel)
            full = os.path.join(resharded_dir, *rel.split("/"))
            if not os.path.isfile(full):
                fail("missing chunk file: %s" % rel)
            actual = os.path.getsize(full)
            if actual != size:
                fail(
                    "chunk size mismatch for %s: expected %d, found %d"
                    % (rel, size, actual)
                )


def rebuild_files(resharded_dir, index):
    for entry in index.get("files", []):
        path = entry["path"]
        dest = os.path.join(resharded_dir, *path.split("/"))
        parent = os.path.dirname(dest)
        if parent:
            os.makedirs(parent, exist_ok=True)
        if os.path.islink(dest) or os.path.isdir(dest):
            fail("cannot reconstruct file over existing non-file: %s" % path)

        tmp = dest + ".__part"
        if os.path.lexists(tmp):
            os.unlink(tmp)
        with open(tmp, "wb") as fdst:
            for rel, _size in entry.get("chunks", []):
                full = os.path.join(resharded_dir, *rel.split("/"))
                with open(full, "rb") as fsrc:
                    while True:
                        block = fsrc.read(BUFFER)
                        if not block:
                            break
                        fdst.write(block)
        actual = os.path.getsize(tmp)
        if actual != entry["size"]:
            fail(
                "reconstructed file size mismatch for %s: "
                "expected %d, found %d" % (path, entry["size"], actual)
            )
        os.replace(tmp, dest)
        try:
            os.chmod(dest, entry["mode"])
        except OSError:
            pass
        try:
            os.utime(dest, (entry["mtime"], entry["mtime"]))
        except OSError:
            pass


def recreate_empty_dirs(resharded_dir, index):
    for rel in index.get("empty_dirs", []):
        os.makedirs(os.path.join(resharded_dir, *rel.split("/")), exist_ok=True)


def remove_reshard(resharded_dir, index, index_path):
    """Delete the chunk files (with their now-empty directories) and the index."""
    chunk_root = os.path.join(resharded_dir, CHUNK_ROOT)
    for dirpath, dirnames, filenames in os.walk(chunk_root, topdown=False):
        for name in filenames:
            os.unlink(os.path.join(dirpath, name))
        for name in dirnames:
            os.rmdir(os.path.join(dirpath, name))
    if os.path.isdir(chunk_root):
        os.rmdir(chunk_root)
    os.unlink(index_path)


def main(argv):
    if len(argv) != 2:
        fail("usage: python decompress.py <resharded_dir>")
    resharded_dir = argv[1]
    if not os.path.isdir(resharded_dir):
        fail("directory does not exist: %s" % resharded_dir)

    index_path, index = load_index(resharded_dir)
    if index.get("format") != "reshard.v1":
        fail("unsupported index format: %r" % index.get("format"))
    verify_index(index)
    verify_chunks(resharded_dir, index)

    rebuild_files(resharded_dir, index)
    recreate_empty_dirs(resharded_dir, index)
    remove_reshard(resharded_dir, index, index_path)
    print("reconstructed %d files in %s" % (len(index.get("files", [])), resharded_dir))


if __name__ == "__main__":
    main(sys.argv)

